import { readFileSync } from 'node:fs';
export type Kernel = 'epanechnikov' | 'biweight' | 'triweight';
export type Direction = 'increasing' | 'decreasing';
export interface Point {
  X: number;
  Y: number;
  x: number;
  y: number;
}
export interface Series {
  name: string;
  points: Point[];
  mode: Direction | 'auto';
}
export interface Candidate {
  text: string;
  value: number;
  hundredths?: number;
}
export interface Estimate {
  value: number | null;
  weights: number[] | null;
}
export interface Fit {
  yhat: number[] | null;
  lev: number[] | null;
  edf: number | null;
  at: (position: number) => Estimate;
}
export interface Settings {
  windows: Candidate[];
  kernels: Kernel[];
  bandwidths: Candidate[];
  degrees: number[];
  spans: Candidate[];
  robustIterations: number;
  lambdas: Candidate[];
  folds: number;
  directions: (Direction | 'auto')[];
  gridPoints: number;
  bandZ: number;
  bandMethods: string[];
  threshold: number;
  bootstrap: number;
  trim: number;
  seed: number;
  plotSeries: string[];
  plotMethods: string[];
  width: number;
  height: number;
}
export function hundredths(text: string): number {
  return Number(text.replace('.', ''));
}
export function readInput() {
  const lines = (name: string) =>
    readFileSync('input/' + name, 'ascii')
      .slice(0, -1)
      .split('\n');
  const fields = new Map(
    lines('params.txt').map((line) => {
      const [name, ...v] = line.split(' ');
      return [name, v];
    }),
  );
  const p = (name: string) => fields.get(name)!;
  const integer = (name: string) => +p(name)[0];
  const decimals = (name: string) =>
    p(name).map((text) => {
      const h = hundredths(text);
      return { text, value: h / 100, hundredths: h };
    });
  const settings: Settings = {
    windows: p('WINDOWS').map((text) => ({ text, value: +text })),
    kernels: p('KERNELS') as Kernel[],
    bandwidths: decimals('BANDWIDTHS'),
    degrees: p('LOESS_DEGREES').map(Number),
    spans: decimals('SPANS'),
    robustIterations: integer('ROBUST_ITERATIONS'),
    lambdas: p('LAMBDAS').map((text) => ({ text, value: +text })),
    folds: integer('CV_FOLDS'),
    directions: p('ISOTONIC') as (Direction | 'auto')[],
    gridPoints: integer('GRID_POINTS'),
    bandZ: +p('BAND_Z')[0],
    bandMethods: p('BAND_METHODS'),
    threshold: hundredths(p('OUTLIER_THRESHOLD')[0]),
    bootstrap: +p('BOOTSTRAP')[0],
    trim: +p('BOOTSTRAP')[1],
    seed: +p('BOOTSTRAP')[2],
    plotSeries: p('PLOT_SERIES'),
    plotMethods: p('PLOT_METHODS'),
    width: +p('PLOT_SIZE')[0],
    height: +p('PLOT_SIZE')[1],
  };
  const byName = new Map<string, Series>();
  for (const line of lines('series.csv').slice(1)) {
    const [name, rawX, rawY] = line.split(',');
    let series = byName.get(name);
    if (!series) {
      series = { name, points: [], mode: settings.directions[byName.size] };
      byName.set(name, series);
    }
    const X = hundredths(rawX);
    const Y = hundredths(rawY);
    series.points.push({ X, Y, x: X / 100, y: Y / 100 });
  }
  const series = [...byName.values()];
  for (const s of series) s.points.sort((a, b) => a.X - b.X);
  const tests = lines('test_points.csv')
    .slice(1)
    .map((line) => {
      const [name, rawX] = line.split(',');
      return { name, X: hundredths(rawX) };
    });
  return { settings, series, tests };
}

import type { Point, Kernel, Fit, Estimate } from './dataset.ts';
export interface KernelEstimate extends Estimate {
  diagonal: number | null;
}
export interface KernelFit extends Fit {
  kind: 'kernel';
}
const CONSTANTS = { epanechnikov: 0.75, biweight: 0.9375, triweight: 1.09375 };
export function kernel(name: Kernel, u: number): number {
  const t = 1 - u * u;
  return name === 'epanechnikov'
    ? 0.75 * t
    : name === 'biweight'
      ? 0.9375 * t * t
      : 1.09375 * t * t * t;
}
export function estimate(
  points: Point[],
  kind: 'nw' | 'll',
  name: Kernel,
  bandwidth: number,
  position: number,
): KernelEstimate {
  const x0 = position / 100;
  const h = bandwidth / 100;
  const used: { index: number; d: number; weight: number }[] = [];
  let s0 = 0;
  let s1 = 0;
  let s2 = 0;
  let t0 = 0;
  let t1 = 0;
  points.forEach((p, j) => {
    if (Math.abs(p.X - position) >= bandwidth) return;
    const d = p.x - x0;
    const w = kernel(name, d / h);
    used.push({ index: j, d, weight: w });
    s0 += w;
    t0 += w * p.y;
    if (kind === 'll') {
      s1 += w * d;
      s2 += w * d * d;
      t1 += w * d * p.y;
    }
  });
  if (used.length < (kind === 'nw' ? 1 : 2)) return { value: null, weights: null, diagonal: null };
  const weights: number[] = Array(points.length).fill(0);
  if (kind === 'nw') {
    for (const p of used) weights[p.index] = p.weight / s0;
    return { value: t0 / s0, weights, diagonal: CONSTANTS[name] / s0 };
  }
  const q = s0 * s2 - s1 * s1;
  for (const p of used) weights[p.index] = (p.weight * (s2 - s1 * p.d)) / q;
  return { value: (s2 * t0 - s1 * t1) / q, weights, diagonal: (CONSTANTS[name] * s2) / q };
}
export function fit(
  points: Point[],
  kind: 'nw' | 'll',
  name: Kernel,
  bandwidth: number,
): KernelFit {
  const at = (position: number) => estimate(points, kind, name, bandwidth, position);
  const estimates = points.map((p) => at(p.X));
  if (estimates.some((e) => e.value === null)) {
    return { kind: 'kernel', yhat: null, lev: null, edf: null, at };
  }
  const lev = estimates.map((e) => e.diagonal!);
  let edf = 0;
  for (const v of lev) edf += v;
  return { kind: 'kernel', yhat: estimates.map((e) => e.value!), lev, edf, at };
}

import type { Point, Fit } from './dataset.ts';
export interface RobustRecord {
  iteration: number;
  scale: number;
  zeros: number;
  change: number;
}
export interface LoessFit extends Fit {
  kind: 'loess';
  yhat: number[];
  lev: number[];
  edf: number;
  robustness: number[];
  records: RobustRecord[];
}
export function median(values: number[]): number {
  const s = [...values].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}
export function cholesky(matrix: number[][]): number[][] {
  const lower: number[][] = matrix.map(() => Array(matrix.length).fill(0));
  for (let k = 0; k < matrix.length; k++) {
    for (let l = 0; l <= k; l++) {
      let sigma = matrix[k][l];
      for (let i = 0; i < l; i++) sigma -= lower[k][i] * lower[l][i];
      lower[k][l] = l === k ? Math.sqrt(sigma) : sigma / lower[l][l];
    }
  }
  return lower;
}
export function solve(lower: number[][], right: number[]): number[] {
  const eta: number[] = [];
  const result: number[] = Array(right.length);
  for (let k = 0; k < right.length; k++) {
    let v = right[k];
    for (let j = 0; j < k; j++) v -= lower[k][j] * eta[j];
    eta.push(v / lower[k][k]);
  }
  for (let k = right.length - 1; k >= 0; k--) {
    let v = eta[k];
    for (let j = k + 1; j < right.length; j++) v -= lower[j][k] * result[j];
    result[k] = v / lower[k][k];
  }
  return result;
}
export function localFit(
  points: Point[],
  degree: number,
  span: number,
  robustness: number[],
  position: number,
) {
  const count = Math.floor((span * points.length) / 100);
  const neighbours = points
    .map((_, i) => i)
    .sort((a, b) => Math.abs(points[a].X - position) - Math.abs(points[b].X - position) || a - b)
    .slice(0, count);
  const extent = Math.abs(points[neighbours[neighbours.length - 1]].X - position);
  neighbours.sort((a, b) => a - b);
  const x0 = position / 100;
  const local = neighbours.map((i) => {
    const a = Math.abs(points[i].X - position) / extent;
    const s = 1 - a * a * a;
    const w = s * s * s;
    const d = points[i].x - x0;
    return { i, weight: w * robustness[i], basis: degree === 1 ? [1, d] : [1, d, d * d] };
  });
  const matrix: number[][] = Array.from({ length: degree + 1 }, () => Array(degree + 1).fill(0));
  const right: number[] = Array(degree + 1).fill(0);
  for (const p of local) {
    for (let k = 0; k <= degree; k++) {
      for (let l = 0; l <= degree; l++) matrix[k][l] += p.weight * p.basis[k] * p.basis[l];
      right[k] += p.weight * p.basis[k] * points[p.i].y;
    }
  }
  const lower = cholesky(matrix);
  const beta = solve(lower, right);
  const unit: number[] = Array(degree + 1).fill(0);
  unit[0] = 1;
  const zeta = solve(lower, unit);
  const weights: number[] = Array(points.length).fill(0);
  for (const p of local) {
    let total = 0;
    for (let k = 0; k <= degree; k++) total += zeta[k] * p.basis[k];
    weights[p.i] = p.weight * total;
  }
  return { value: beta[0], weights, zeta0: zeta[0] };
}
export function fit(points: Point[], degree: number, span: number, iterations: number): LoessFit {
  let robustness = points.map(() => 1);
  let estimates = points.map((p) => localFit(points, degree, span, robustness, p.X));
  const records: RobustRecord[] = [];
  for (let iteration = 1; iteration <= iterations; iteration++) {
    const errors = points.map((p, i) => p.y - estimates[i].value);
    const scale = median(errors.map(Math.abs));
    robustness = errors.map((e) => {
      const u = e / (6 * scale);
      if (Math.abs(u) >= 1) return 0;
      const v = 1 - u * u;
      return v * v;
    });
    const next = points.map((p) => localFit(points, degree, span, robustness, p.X));
    let change = 0;
    for (let i = 0; i < points.length; i++) {
      change = Math.max(change, Math.abs(next[i].value - estimates[i].value));
    }
    records.push({ iteration, scale, zeros: robustness.filter((v) => v === 0).length, change });
    estimates = next;
  }
  const lev = estimates.map((e, i) => robustness[i] * e.zeta0);
  let edf = 0;
  for (const v of lev) edf += v;
  return {
    kind: 'loess',
    yhat: estimates.map((e) => e.value),
    lev,
    edf,
    robustness,
    records,
    at: (position: number) => localFit(points, degree, span, robustness, position),
  };
}

import { mkdirSync, writeFileSync } from 'node:fs';
import {
  readInput,
  type Point,
  type Series,
  type Settings,
  type Candidate,
  type Kernel,
  type Direction,
  type Fit,
  type Estimate,
} from './dataset.ts';
import * as kernels from './kernels.ts';
import * as loess from './loess.ts';
import * as spline from './spline.ts';
import * as selection from './selection.ts';

type Method =
  | { name: string; kind: 'linear' | 'isotonic' }
  | { name: string; kind: 'mean' | 'median'; candidates: Candidate[] }
  | { name: string; kind: 'nw' | 'll'; kernel: Kernel; candidates: Candidate[] }
  | { name: string; kind: 'loess'; degree: number; candidates: Candidate[] }
  | { name: string; kind: 'spline'; candidates: Candidate[] };
interface BasicFit extends Fit {
  kind: 'linear' | 'running';
  yhat: number[];
}
interface Block {
  first: number;
  last: number;
  total: number;
  count: number;
  value: number;
}
interface IsotonicFit extends Fit {
  kind: 'isotonic';
  yhat: number[];
  blocks: Block[];
  direction: Direction;
}
type FitResult = BasicFit | IsotonicFit | kernels.KernelFit | loess.LoessFit | spline.SplineFit;
interface Model {
  fit: FitResult;
  method: Method;
  name: string;
  order: number;
  chosen: Candidate | null;
  parameter: string;
  selected: number;
  candidates: { parameter: string; score: number | null; edf: number | null }[];
  loo: number;
  kfold: number | null;
  increasingRSS: number | null;
  decreasingRSS: number | null;
  yhat: number[];
  lev: number[] | null;
  edf: number | null;
}
function sum(values: number[]): number {
  let total = 0;
  for (const v of values) total += v;
  return total;
}
function squares(values: number[]): number {
  let total = 0;
  for (const v of values) total += v * v;
  return total;
}
function residualSum(points: Point[], fitted: number[]): number {
  return squares(points.map((p, i) => p.y - fitted[i]));
}
function real(value: number | null): string {
  if (value === null) return 'NA';
  if (Math.abs(value) >= 1e21) {
    return (value < 0 ? '-' : '') + BigInt(Math.abs(value)).toString() + '.0000';
  }
  const text = value.toFixed(4);
  return +text === 0 ? '0.0000' : text;
}
function hundredths(value: number): string {
  const n = Math.abs(value);
  return `${value < 0 ? '-' : ''}${Math.floor(n / 100)}.${String(n % 100).padStart(2, '0')}`;
}
function methodList(settings: Settings): Method[] {
  const methods: Method[] = [
    { name: 'linear', kind: 'linear' },
    { name: 'running_mean', kind: 'mean', candidates: settings.windows },
    { name: 'running_median', kind: 'median', candidates: settings.windows },
  ];
  for (const kind of ['nw', 'll'] as const) {
    for (const kernel of settings.kernels) {
      methods.push({ name: kind + '_' + kernel, kind, kernel, candidates: settings.bandwidths });
    }
  }
  for (const degree of settings.degrees) {
    methods.push({ name: 'loess' + degree, kind: 'loess', degree, candidates: settings.spans });
  }
  return [
    ...methods,
    { name: 'spline', kind: 'spline', candidates: settings.lambdas },
    { name: 'isotonic', kind: 'isotonic' },
  ];
}
function fitLinear(points: Point[]): BasicFit {
  const n = points.length;
  const xbar = sum(points.map((p) => p.x)) / n;
  const ybar = sum(points.map((p) => p.y)) / n;
  let sxx = 0;
  let sxy = 0;
  for (const p of points) {
    const d = p.x - xbar;
    sxx += d * d;
    sxy += d * (p.y - ybar);
  }
  const b = sxy / sxx;
  const a = ybar - b * xbar;
  return {
    kind: 'linear',
    yhat: points.map((p) => a + b * p.x),
    edf: 2,
    lev: points.map((p) => 1 / n + ((p.x - xbar) * (p.x - xbar)) / sxx),
    at: (position: number) => ({
      value: a + b * (position / 100),
      weights: points.map((p) => 1 / n + ((position / 100 - xbar) * (p.x - xbar)) / sxx),
    }),
  };
}
function nearestPoint(points: Point[], position: number): number {
  let nearest = 0;
  for (let i = 1; i < points.length; i++) {
    if (Math.abs(points[i].X - position) < Math.abs(points[nearest].X - position)) nearest = i;
  }
  return nearest;
}
function fitRunning(points: Point[], width: number, median: boolean): BasicFit {
  const radii = points.map((_, i) => Math.min((width - 1) / 2, i, points.length - 1 - i));
  const yhat = radii.map((r, i) => {
    const values = points.slice(i - r, i + r + 1).map((p) => p.Y);
    return median ? values.sort((a, b) => a - b)[r] / 100 : sum(values) / (100 * (2 * r + 1));
  });
  const lev = median ? null : radii.map((r) => 1 / (2 * r + 1));
  return {
    kind: 'running',
    yhat,
    lev,
    edf: lev === null ? null : sum(lev),
    at: (position: number) => {
      const c = nearestPoint(points, position);
      let weights: number[] | null = null;
      if (!median) {
        weights = points.map(() => 0);
        for (let j = c - radii[c]; j <= c + radii[c]; j++) weights[j] = 1 / (2 * radii[c] + 1);
      }
      return { value: yhat[c], weights };
    },
  };
}
function fitIsotonic(points: Point[], direction: Direction): IsotonicFit {
  const blocks: Block[] = [];
  points.forEach((p, i) => {
    blocks.push({ first: i, last: i, total: p.Y, count: 1, value: 0 });
    while (blocks.length >= 2) {
      const a = blocks[blocks.length - 2];
      const b = blocks[blocks.length - 1];
      const left = a.total * b.count;
      const right = b.total * a.count;
      if (direction === 'increasing' ? left <= right : left >= right) break;
      blocks.splice(-2, 2, {
        first: a.first,
        last: b.last,
        total: a.total + b.total,
        count: a.count + b.count,
        value: 0,
      });
    }
  });
  const yhat: number[] = Array(points.length);
  for (const b of blocks) {
    b.value = b.total / (100 * b.count);
    for (let i = b.first; i <= b.last; i++) yhat[i] = b.value;
  }
  return {
    kind: 'isotonic',
    yhat,
    lev: null,
    edf: blocks.length,
    blocks,
    direction,
    at: (position: number) => {
      let i = 0;
      while (i + 1 < points.length && points[i + 1].X <= position) i++;
      return { value: yhat[i], weights: null };
    },
  };
}
function fitFull(
  method: Method,
  candidate: Candidate | null,
  points: Point[],
  iterations = 0,
  direction: Direction = 'increasing',
): FitResult {
  switch (method.kind) {
    case 'linear':
      return fitLinear(points);
    case 'mean':
    case 'median':
      return fitRunning(points, candidate!.value, method.kind === 'median');
    case 'nw':
    case 'll':
      return kernels.fit(points, method.kind, method.kernel, candidate!.hundredths!);
    case 'loess':
      return loess.fit(points, method.degree, candidate!.hundredths!, iterations);
    case 'spline':
      return spline.fit(points, candidate!.value);
    case 'isotonic':
      return fitIsotonic(points, direction);
  }
}
function subsetEstimator(
  method: Method,
  candidate: Candidate | null,
  points: Point[],
  direction: Direction = 'increasing',
): (position: number) => number | null {
  if (method.kind === 'nw' || method.kind === 'll') {
    return (x) =>
      kernels.estimate(points, method.kind, method.kernel, candidate!.hundredths!, x).value;
  }
  if (method.kind === 'loess') {
    const rho = points.map(() => 1);
    return (x) => loess.localFit(points, method.degree, candidate!.hundredths!, rho, x).value;
  }
  const fit =
    method.kind === 'spline'
      ? spline.fit(points, candidate!.value, false)
      : fitFull(method, candidate, points, 0, direction);
  return (x) => fit.at(x).value;
}
function leaveOneOut(
  method: Method,
  candidate: Candidate | null,
  points: Point[],
  direction?: Direction,
): number | null {
  const predictions = points.map((p, i) =>
    subsetEstimator(
      method,
      candidate,
      points.filter((_, j) => j !== i),
      direction,
    )(p.X),
  );
  return selection.crossValidation(
    points.map((p) => p.y),
    predictions,
  );
}
function kfold(
  method: Method,
  candidate: Candidate | null,
  points: Point[],
  direction: Direction | undefined,
  groups: number,
): number | null {
  const predictions: (number | null)[] = Array(points.length);
  for (let g = 0; g < groups; g++) {
    const at = subsetEstimator(
      method,
      candidate,
      points.filter((_, i) => i % groups !== g),
      direction,
    );
    for (let i = g; i < points.length; i += groups) predictions[i] = at(points[i].X);
  }
  return selection.crossValidation(
    points.map((p) => p.y),
    predictions,
  );
}
function fitMethods(series: Series, settings: Settings, methods: Method[]): Model[] {
  const points = series.points;
  return methods.map((method, order) => {
    let fit: FitResult;
    let chosen: Candidate | null = null;
    let selected = -1;
    let parameter = '-';
    let loo: number | null;
    let increasingRSS: number | null = null;
    let decreasingRSS: number | null = null;
    let candidates: Model['candidates'] = [];
    if (method.kind === 'linear') {
      fit = fitLinear(points);
      loo = leaveOneOut(method, null, points);
    } else if (method.kind === 'isotonic') {
      let iso: IsotonicFit;
      if (series.mode === 'auto') {
        const inc = fitIsotonic(points, 'increasing');
        const dec = fitIsotonic(points, 'decreasing');
        increasingRSS = residualSum(points, inc.yhat);
        decreasingRSS = residualSum(points, dec.yhat);
        iso = increasingRSS <= decreasingRSS ? inc : dec;
      } else iso = fitIsotonic(points, series.mode);
      fit = iso;
      parameter = iso.direction;
      loo = leaveOneOut(method, null, points, iso.direction);
    } else {
      const evaluated = method.candidates.map((candidate) => {
        const fit = fitFull(method, candidate, points);
        const score =
          method.kind === 'spline'
            ? selection.generalized(
                points.map((p) => p.y),
                fit.yhat!,
                fit.edf!,
              )
            : leaveOneOut(method, candidate, points);
        return { candidate, fit, score, edf: fit.edf };
      });
      selected = selection.choose(evaluated);
      const winner = evaluated[selected];
      chosen = winner.candidate;
      parameter = chosen.text;
      fit =
        method.kind === 'loess' && settings.robustIterations > 0
          ? fitFull(method, chosen, points, settings.robustIterations)
          : winner.fit;
      loo = method.kind === 'spline' ? leaveOneOut(method, chosen, points) : winner.score;
      candidates = evaluated.map((e) => ({
        parameter: e.candidate.text,
        score: e.score,
        edf: e.edf,
      }));
    }
    return {
      fit,
      method,
      name: method.name,
      order,
      chosen,
      parameter,
      selected,
      candidates,
      loo: loo!,
      increasingRSS,
      decreasingRSS,
      yhat: fit.yhat!,
      lev: fit.lev,
      edf: fit.edf,
      kfold: kfold(
        method,
        chosen,
        points,
        fit.kind === 'isotonic' ? fit.direction : undefined,
        settings.folds,
      ),
    };
  });
}
function turningCount(estimates: Estimate[]): number {
  const values = estimates.map((e) => e.value).filter((v): v is number => v !== null);
  let previous = 0;
  let count = 0;
  for (let i = 1; i < values.length; i++) {
    const delta = values[i] - values[i - 1];
    if (delta === 0) continue;
    const sign = delta > 0 ? 1 : -1;
    if (previous && previous !== sign) count++;
    previous = sign;
  }
  return count;
}
function diagnostics(points: Point[], model: Model, grid: Estimate[], linearRSS: number) {
  const n = points.length;
  const errors = points.map((p, i) => p.y - model.yhat[i]);
  const rss = squares(errors);
  const ybar = sum(points.map((p) => p.y)) / n;
  const tss = squares(points.map((p) => p.y - ybar));
  const df = model.edf === null ? null : n - model.edf;
  const rse = df === null ? null : Math.sqrt(rss / df);
  const nonlinear =
    model.name !== 'linear' && model.edf !== null && model.edf > 2
      ? (linearRSS - rss) / (model.edf - 2) / (rss / df!)
      : null;
  const mean = sum(errors) / n;
  const centered = errors.map((e) => e - mean);
  const denominator = squares(centered);
  const acf: number[] = [];
  for (let lag = 1; lag <= 5; lag++) {
    let numerator = 0;
    for (let i = 0; i < n - lag; i++) numerator += centered[i] * centered[i + lag];
    acf.push(numerator / denominator);
  }
  let successive = 0;
  let positive = 0;
  let negative = 0;
  let runs = 0;
  let previous = 0;
  let largest = 0;
  for (let i = 0; i < n; i++) {
    if (i) {
      const d = errors[i] - errors[i - 1];
      successive += d * d;
    }
    if (Math.abs(errors[i]) > Math.abs(errors[largest])) largest = i;
    if (errors[i] === 0) continue;
    const sign = errors[i] > 0 ? 1 : -1;
    if (sign > 0) positive++;
    else negative++;
    if (sign !== previous) runs++;
    previous = sign;
  }
  const nonzero = positive + negative;
  const pairs = 2 * positive * negative;
  const mu = 1 + pairs / nonzero;
  const variance = (pairs * (pairs - nonzero)) / (nonzero * nonzero * (nonzero - 1));
  const sorted = [...errors].sort((a, b) => a - b);
  const quantiles = [0, 1, 2, 3, 4].map((k) => {
    const j = Math.floor(((n - 1) * k) / 4);
    const r = (n - 1) * k - 4 * j;
    return r === 0 ? sorted[j] : sorted[j] + (r / 4) * (sorted[j + 1] - sorted[j]);
  });
  return {
    errors,
    rss,
    df,
    rse,
    r2: 1 - rss / tss,
    nonlinear,
    acf,
    dw: successive / rss,
    positive,
    negative,
    runs,
    runsZ: (runs - mu) / Math.sqrt(variance),
    largest,
    quantiles,
    turning: turningCount(grid),
  };
}
type AnalyzedModel = Model & { grid: Estimate[]; diagnostics: ReturnType<typeof diagnostics> };
function compareFits(models: AnalyzedModel[], grid: number[], settings: Settings) {
  const ranking = [...models].sort((a, b) => a.loo - b.loo || a.order - b.order);
  const best = ranking[0];
  const agreements = models
    .filter((m) => m !== best)
    .map((m) => {
      let count = 0;
      let total = 0;
      let maximum = -1;
      let position = grid[0];
      for (let k = 0; k < grid.length; k++) {
        const a = m.grid[k].value;
        const b = best.grid[k].value;
        if (a === null || b === null) continue;
        const delta = Math.abs(a - b);
        count++;
        total += delta * delta;
        if (delta > maximum) {
          maximum = delta;
          position = grid[k];
        }
      }
      return { name: m.name, count, rms: Math.sqrt(total / count), maximum, position };
    });
  const spl = models.find((m) => m.name === 'spline')!;
  let maximum = -Infinity;
  let minimum = Infinity;
  let maxPosition = grid[1];
  let minPosition = grid[1];
  for (let k = 1; k < grid.length - 1; k++) {
    const slope =
      (spl.grid[k + 1].value! - spl.grid[k - 1].value!) / ((grid[k + 1] - grid[k - 1]) / 100);
    if (slope > maximum) {
      maximum = slope;
      maxPosition = grid[k];
    }
    if (slope < minimum) {
      minimum = slope;
      minPosition = grid[k];
    }
  }
  const outlierMethod = ranking.find((m) => m.lev !== null)!;
  const standardized: { index: number; t: number; cook: number }[] = [];
  outlierMethod.lev!.forEach((lev, i) => {
    if (lev >= 1) return;
    const t =
      outlierMethod.diagnostics.errors[i] / (outlierMethod.diagnostics.rse! * Math.sqrt(1 - lev));
    standardized.push({ index: i, t, cook: (t * t * lev) / ((1 - lev) * outlierMethod.edf!) });
  });
  return {
    ranking,
    best,
    agreements,
    slope: { maximum, minimum, maxPosition, minPosition },
    outlierMethod,
    standardized,
    outliers: standardized
      .filter((e) => Math.abs(e.t) > settings.threshold / 100)
      .sort((a, b) => Math.abs(b.t) - Math.abs(a.t) || a.index - b.index),
    influence: [...standardized].sort((a, b) => b.cook - a.cook || a.index - b.index).slice(0, 3),
  };
}
interface BandValue {
  fit: number | null;
  se: number | null;
  lower: number | null;
  upper: number | null;
}
function variabilityBands(points: Point[], models: AnalyzedModel[], settings: Settings) {
  return settings.bandMethods.map((name) => {
    const model = models.find((m) => m.name === name)!;
    const rse = model.diagnostics.rse!;
    let total = 0;
    let count = 0;
    const values: BandValue[] = model.grid.map((e) => {
      if (e.value === null) return { fit: null, se: null, lower: null, upper: null };
      const se = rse * Math.sqrt(squares(e.weights!));
      total += se;
      count++;
      return {
        fit: e.value,
        se,
        lower: e.value - settings.bandZ * se,
        upper: e.value + settings.bandZ * se,
      };
    });
    let coverage = 0;
    points.forEach((p, i) => {
      const se = rse * Math.sqrt(squares(model.fit.at(p.X).weights!));
      if (
        Math.abs(model.diagnostics.errors[i]) <=
        settings.bandZ * Math.sqrt(rse * rse + se * se)
      ) {
        coverage++;
      }
    });
    return { name, values, meanSE: total / count, coverage };
  });
}
function bootstrapIntervals(
  model: AnalyzedModel,
  grid: number[],
  settings: Settings,
  draw: () => number,
): BandValue[] {
  if (model.fit.kind !== 'spline') throw new Error('Bootstrap requires a spline');
  const system = model.fit.system;
  const residuals = model.diagnostics.errors;
  const mean = sum(residuals) / residuals.length;
  const centered = residuals.map((e) => e - mean);
  const samples: number[][] = grid.map(() => []);
  for (let b = 0; b < settings.bootstrap; b++) {
    const values = model.yhat.map((y) => y + centered[draw() % residuals.length]);
    const curve = system.fit(values);
    grid.forEach((x, k) => samples[k].push(system.evaluate(curve, x)));
  }
  return samples.map((values, k) => {
    const average = sum(values) / settings.bootstrap;
    const se = Math.sqrt(squares(values.map((v) => v - average)) / (settings.bootstrap - 1));
    const sorted = [...values].sort((a, b) => a - b);
    return {
      fit: model.grid[k].value,
      se,
      lower: sorted[settings.trim],
      upper: sorted[settings.bootstrap - settings.trim - 1],
    };
  });
}
function processSeries(series: Series, settings: Settings, methods: Method[], draw: () => number) {
  const points = series.points;
  const last = points[points.length - 1];
  const grid = Array.from(
    { length: settings.gridPoints },
    (_, k) => points[0].X + Math.floor((k * (last.X - points[0].X)) / (settings.gridPoints - 1)),
  );
  const fitted = fitMethods(series, settings, methods);
  const linearRSS = residualSum(points, fitted[0].yhat);
  const models = fitted.map((m) => {
    const estimates = grid.map((x) => m.fit.at(x));
    return { ...m, grid: estimates, diagnostics: diagnostics(points, m, estimates, linearRSS) };
  });
  return {
    series,
    grid,
    models,
    comparison: compareFits(models, grid, settings),
    bands: variabilityBands(points, models, settings),
    bootstrap: bootstrapIntervals(
      models.find((m) => m.name === 'spline')!,
      grid,
      settings,
      draw,
    ),
    minY: Math.min(...points.map((p) => p.Y)),
    maxY: Math.max(...points.map((p) => p.Y)),
  };
}
type Result = ReturnType<typeof processSeries>;
function diagnosticsBlock(result: Result, settings: Settings): string[] {
  const { series: s, models, comparison: c, bands } = result;
  const points = s.points;
  const lines = [
    `series ${s.name} n ${points.length} x ${hundredths(points[0].X)} ${hundredths(points[points.length - 1].X)} y ${hundredths(result.minY)} ${hundredths(result.maxY)}`,
  ];
  for (const m of models) {
    const d = m.diagnostics;
    lines.push(
      `method ${m.name} parameter ${m.parameter} loo ${real(m.loo)}` +
        (m.name === 'spline' ? ` gcv ${real(m.candidates[m.selected].score)}` : ''),
      `  rss ${real(d.rss)} edf ${real(m.edf)} df ${real(d.df)} rse ${real(d.rse)} r2 ${real(d.r2)} f_nonlinear ${real(d.nonlinear)}`,
      `  acf ${d.acf.map(real).join(' ')} dw ${real(d.dw)}`,
      `  runs ${d.runs} positive ${d.positive} negative ${d.negative} z ${real(d.runsZ)}`,
