        );
      }
      const zeros = points.filter((_, i) => fit.robustness[i] === 0).map((p) => hundredths(p.X));
      lines.push('  zero_weight_points ' + (zeros.length ? zeros.join(' ') : 'none'));
    }
  }
  lines.push(
    'ranking',
    ...c.ranking.map((m, i) => `  ${i + 1} ${m.name} ${real(m.loo)} kfold ${real(m.kfold)}`),
    'agreement with ' + c.best.name,
    ...c.agreements.map(
      (a) =>
        `  ${a.name} points ${a.count} rms ${real(a.rms)} max ${real(a.maximum)} at ${hundredths(a.position)}`,
    ),
  );
  const slope = c.slope;
  const outlier = c.outlierMethod;
  lines.push(
    `slope spline max ${real(slope.maximum)} at ${hundredths(slope.maxPosition)} min ${real(slope.minimum)} at ${hundredths(slope.minPosition)}`,
    `outliers method ${outlier.name} threshold ${hundredths(settings.threshold)}`,
  );
  if (!c.outliers.length) lines.push('  none');
  for (const i of c.outliers) {
    const p = points[i.index];
    lines.push(
      `  x ${hundredths(p.X)} y ${hundredths(p.Y)} fit ${real(outlier.yhat[i.index])} residual ${real(outlier.diagnostics.errors[i.index])} standardized ${real(i.t)}`,
    );
  }
  lines.push(
    'influence method ' + outlier.name,
    ...c.influence.map(
      (i) =>
        `  x ${hundredths(points[i.index].X)} lev ${real(outlier.lev![i.index])} cook ${real(i.cook)}`,
    ),
    'bands',
    ...bands.map(
      (b) => `  ${b.name} mean_se ${real(b.meanSE)} coverage ${b.coverage} of ${points.length}`,
    ),
  );
