}
function isotonicBlock(result: Result): string[] {
  const s = result.series;
  const m = result.models.find((m) => m.name === 'isotonic')!;
  if (m.fit.kind !== 'isotonic') throw new Error('Expected isotonic fit');
  const heading =
    `series ${s.name} direction ${m.fit.direction} mode ${s.mode}` +
    (s.mode === 'auto'
      ? ` rss_increasing ${real(m.increasingRSS)} rss_decreasing ${real(m.decreasingRSS)}`
      : '');
  return [
    heading,
    `blocks ${m.fit.blocks.length} rss ${real(m.diagnostics.rss)} loo ${real(m.loo)}`,
    ...m.fit.blocks.map(
      (b, i) =>
        `block ${i + 1} x ${hundredths(s.points[b.first].X)} ${hundredths(s.points[b.last].X)} count ${b.count} value ${real(b.value)}`,
    ),
  ];
}
function frame(cells: string[][]): string[] {
  const border = '+' + '-'.repeat(cells[0].length) + '+';
  return [border, ...cells.map((row) => '|' + row.join('') + '|'), border];
}
function histogram(standardized: { t: number }[]): string[] {
  const counts: number[] = Array(14).fill(0);
  for (const { t } of standardized) {
    let bin = 0;
    if (t >= 3) bin = 13;
    else if (t >= -3) {
      bin = 1;
      while (t >= -3 + 0.5 * bin) bin++;
    }
    counts[bin]++;
  }
  return counts.map(
    (n, k) =>
      `${k === 0 ? '-inf' : hundredths(-300 + 50 * (k - 1))} ${k === 13 ? 'inf' : hundredths(-300 + 50 * k)} ${n} |${'#'.repeat(n)}`,
  );
}
function plotBlock(result: Result, settings: Settings): string[] {
  const { series: s, models, comparison: c, minY, maxY } = result;
  const { width: w, height: h } = settings;
  const points = s.points;
  const firstX = points[0].X;
  const lastX = points[points.length - 1].X;
  const ymin = minY / 100;
  const ymax = maxY / 100;
  const blank = (): string[][] => Array.from({ length: h }, () => Array(w).fill(' '));
  const clampRow = (v: number) => Math.max(0, Math.min(h - 1, Math.floor(v)));
  const column = (p: Point) => Math.min(w - 1, Math.floor((w * (p.X - firstX)) / (lastX - firstX)));
  const cells = blank();
  for (const p of points) {
    cells[Math.min(h - 1, Math.floor((h * (maxY - p.Y)) / (maxY - minY)))][column(p)] = '.';
  }
  settings.plotMethods.forEach((name, i) => {
    const model = models.find((m) => m.name === name)!;
    const digit = String(i + 1);
    for (let col = 0; col < w; col++) {
      const x = firstX + Math.floor(((2 * col + 1) * (lastX - firstX)) / (2 * w));
      const v = model.fit.at(x).value;
      if (v === null) continue;
      const row = clampRow((h * (ymax - v)) / (ymax - ymin));
      const old = cells[row][col];
      cells[row][col] = old === ' ' || old === '.' || old === digit ? digit : '*';
    }
  });
  let data = 0;
  let curve = 0;
  let overlap = 0;
  for (const row of cells) {
    for (const ch of row) {
      if (ch === '.') data++;
      else if (ch === '*') overlap++;
      else if (ch >= '1' && ch <= '9') curve++;
    }
  }
  const residuals = blank();
  const errors = c.best.diagnostics.errors;
  residuals[Math.floor(h / 2)].fill('-');
  let limit = 0;
  for (const e of errors) limit = Math.max(limit, Math.abs(e));
  points.forEach((p, i) => {
    residuals[clampRow(h * ((limit - errors[i]) / (2 * limit)))][column(p)] = 'o';
  });
  return [
    `plot ${s.name} size ${w}x${h} x ${hundredths(firstX)} ${hundredths(lastX)} y ${hundredths(minY)} ${hundredths(maxY)}`,
    'legend . data ' + settings.plotMethods.map((name, i) => `${i + 1} ${name}`).join(' '),
    ...frame(cells),
    `cells data ${data} curve ${curve} overlap ${overlap}`,
    '',
    `residuals ${s.name} method ${c.best.name} limit ${real(limit)}`,
    ...frame(residuals),
    '',
    `histogram ${s.name} method ${c.outlierMethod.name}`,
    ...histogram(c.standardized),
  ];
}
function joinBlocks(blocks: string[][]): string[] {
  return blocks.flatMap((b, i) => (i ? ['', ...b] : b));
}
function main(): void {
  const { settings, series, tests } = readInput();
  const methods = methodList(settings);
  let state = settings.seed;
  const draw = () => {
    state = (48271 * state) % 2147483647;
    return state;
  };
  const results = series.map((s) => processSeries(s, settings, methods, draw));
  const byName = new Map(results.map((r) => [r.series.name, r]));
  const header = 'series,x,' + methods.map((m) => m.name).join(',');
  const selected = ['series,method,parameter,score,edf,selected'];
  const fits = [header];
  const predictions = [header];
  const bands = ['series,method,x,fit,se,lower,upper'];
  for (const r of results) {
    const name = r.series.name;
    for (const m of r.models) {
      m.candidates.forEach((c, i) =>
        selected.push(
          [name, m.name, c.parameter, real(c.score), real(c.edf), i === m.selected ? 1 : 0].join(
            ',',
          ),
        ),
      );
    }
    r.grid.forEach((x, k) =>
      fits.push([name, hundredths(x), ...r.models.map((m) => real(m.grid[k].value))].join(',')),
    );
    for (const b of [...r.bands, { name: 'spline_bootstrap', values: r.bootstrap }]) {
      b.values.forEach((v, k) =>
        bands.push(
          [
            name,
            b.name,
            hundredths(r.grid[k]),
            real(v.fit),
            real(v.se),
            real(v.lower),
            real(v.upper),
          ].join(','),
        ),
      );
    }
  }
  for (const t of tests) {
    predictions.push(
      [
        t.name,
        hundredths(t.X),
        ...byName.get(t.name)!.models.map((m) => real(m.fit.at(t.X).value)),
      ].join(','),
    );
  }
  const reports: Record<string, string[]> = {
    'selection.csv': selected,
    'fits.csv': fits,
    'predictions.csv': predictions,
    'bands.csv': bands,
    'diagnostics.txt': joinBlocks(results.map((r) => diagnosticsBlock(r, settings))),
    'isotonic.txt': joinBlocks(results.map(isotonicBlock)),
    'plots.txt': joinBlocks(
      settings.plotSeries.map((name) => plotBlock(byName.get(name)!, settings)),
    ),
  };
  mkdirSync('output', { recursive: true });
  for (const [name, lines] of Object.entries(reports)) {
    writeFileSync('output/' + name, lines.join('\n') + '\n', 'ascii');
  }
}
main();

export function crossValidation(actual: number[], predictions: (number | null)[]): number | null {
  let total = 0;
  for (let i = 0; i < actual.length; i++) {
    const p = predictions[i];
    if (p === null) return null;
    const e = actual[i] - p;
    total += e * e;
  }
  return total / actual.length;
}
export function generalized(actual: number[], fitted: number[], edf: number): number {
  let rss = 0;
  for (let i = 0; i < actual.length; i++) {
    const e = actual[i] - fitted[i];
    rss += e * e;
  }
  const tau = 1 - edf / actual.length;
  return rss / actual.length / (tau * tau);
}
export function choose(candidates: { score: number | null }[]): number {
  let best = -1;
  for (let i = 0; i < candidates.length; i++) {
    const s = candidates[i].score;
    if (s !== null && (best < 0 || s < candidates[best].score!)) best = i;
  }
  return best;
}

import type { Point, Fit } from './dataset.ts';
export interface Curve {
  g: number[];
  gamma: number[];
}
export interface SplineFit extends Fit {
  kind: 'spline';
  yhat: number[];
  system: SmoothingSpline;
  curve: Curve;
}
export class SmoothingSpline {
  positions: number[];
  x: number[];
  h: number[];
  lower1: number[] = [];
  lower2: number[] = [];
  diagonal: number[] = [];
  constructor(
    points: Point[],
    public lambda: number,
  ) {
    this.positions = points.map((p) => p.X);
    this.x = points.map((p) => p.x);
    this.h = this.x.slice(1).map((v, i) => v - this.x[i]);
    const count = points.length - 2;
    const a = Array.from({ length: count }, (_, k) => 1 / this.h[k]);
    const c = Array.from({ length: count }, (_, k) => 1 / this.h[k + 1]);
    const b = a.map((v, k) => -(v + c[k]));
    const diagonal = a.map(
      (v, k) => (this.h[k] + this.h[k + 1]) / 3 + lambda * (v * v + b[k] * b[k] + c[k] * c[k]),
    );
    const first = Array.from(
      { length: count - 1 },
      (_, k) => this.h[k + 1] / 6 + lambda * c[k] * (b[k] + b[k + 1]),
    );
    const second = Array.from({ length: count - 2 }, (_, k) => lambda * c[k] * c[k + 1]);
    for (let k = 0; k < count; k++) {
      const d1 = this.diagonal[k - 1] ?? 0;
      const d2 = this.diagonal[k - 2] ?? 0;
      const l2 = k >= 2 ? second[k - 2] / d2 : 0;
      const l1 = k >= 1 ? (first[k - 1] - l2 * d2 * this.lower1[k - 1]) / d1 : 0;
      this.lower1.push(l1);
      this.lower2.push(l2);
      this.diagonal.push(diagonal[k] - l1 * l1 * d1 - l2 * l2 * d2);
    }
  }
  fit(values: number[]): Curve {
    const z: number[] = [];
    for (let k = 0; k < values.length - 2; k++) {
      const phi =
        (values[k + 2] - values[k + 1]) / this.h[k + 1] - (values[k + 1] - values[k]) / this.h[k];
      z.push(phi - this.lower1[k] * (z[k - 1] ?? 0) - this.lower2[k] * (z[k - 2] ?? 0));
    }
    const gamma: number[] = Array(values.length).fill(0);
    for (let k = z.length - 1; k >= 0; k--) {
      gamma[k + 1] =
        z[k] / this.diagonal[k] -
        (this.lower1[k + 1] ?? 0) * gamma[k + 2] -
        (this.lower2[k + 2] ?? 0) * (gamma[k + 3] ?? 0);
    }
    const g = values.map((v, i) => {
      const omega =
        i === 0
          ? (gamma[1] - gamma[0]) / this.h[0]
          : i === values.length - 1
            ? 0 - (gamma[i] - gamma[i - 1]) / this.h[i - 1]
            : (gamma[i + 1] - gamma[i]) / this.h[i] - (gamma[i] - gamma[i - 1]) / this.h[i - 1];
      return v - this.lambda * omega;
    });
    return { g, gamma };
  }
  evaluate({ g, gamma }: Curve, position: number): number {
    const x0 = position / 100;
    const last = this.x.length - 1;
    if (position < this.positions[0]) {
      const tau = (g[1] - g[0]) / this.h[0] - (this.h[0] * gamma[1]) / 6;
      return g[0] - (this.x[0] - x0) * tau;
    }
    if (position > this.positions[last]) {
      const tau =
        (g[last] - g[last - 1]) / this.h[last - 1] + (this.h[last - 1] * gamma[last - 1]) / 6;
      return g[last] + (x0 - this.x[last]) * tau;
    }
    let low = 0;
    let high = this.positions.length;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (this.positions[mid] < position) low = mid + 1;
      else high = mid;
    }
    if (this.positions[low] === position) return g[low];
    const i = low - 1;
    const pl = x0 - this.x[i];
    const pr = this.x[i + 1] - x0;
    return (
      (pl * g[i + 1] + pr * g[i]) / this.h[i] -
